-- 1) SIRUTA-alapú UPDATE — ha a helység már létezik a táblában és van SIRUTA-ja
UPDATE public.adrlocality l
SET
  name_hu = COALESCE(s.name_hu, l.name_hu),
  name_ro = s.name_ro,
  default_postalcode = s.default_postalcode,
  geonames_id = s.geonames_id,
  feature_code = s.feature_code
FROM _adr_loc_staging s
WHERE l.siruta_code = s.siruta_code;

-- 2) NÉV-alapú UPDATE a régi magyar nevezésű sorokra (SIRUTA még NULL)
UPDATE public.adrlocality l
SET
  name_hu = l.name,  -- a régi magyar név HU-ként megmarad
  name_ro = s.name_ro,
  default_postalcode = s.default_postalcode,
  siruta_code = s.siruta_code,
  geonames_id = s.geonames_id,
  feature_code = s.feature_code,
  countyid = (SELECT id FROM public.adrcounty WHERE siruta_code = s.county_siruta LIMIT 1)
FROM _adr_loc_staging s
WHERE l.siruta_code IS NULL
  AND (lower(l.name) = lower(s.name_hu) OR lower(l.name) = lower(s.name_ro));

-- 3) Új helységek (a staging-ből, amely még nem létezik SIRUTA alapján)
-- ON CONFLICT (name, countyid) DO NOTHING — az adrlocality tábla unique indexét kezeli
INSERT INTO public.adrlocality (name, countyid, name_hu, name_ro, siruta_code, default_postalcode, geonames_id, feature_code)
SELECT
  COALESCE(s.name_hu, s.name_ro) AS name,
  c.id AS countyid,
  s.name_hu,
  s.name_ro,
  s.siruta_code,
  s.default_postalcode,
  s.geonames_id,
  s.feature_code
FROM _adr_loc_staging s
JOIN public.adrcounty c ON c.siruta_code = s.county_siruta
WHERE NOT EXISTS (
  SELECT 1 FROM public.adrlocality l WHERE l.siruta_code = s.siruta_code
)
ON CONFLICT (name, countyid) DO NOTHING;

DROP TABLE _adr_loc_staging;

COMMIT;

-- Ellenőrzés
SELECT COUNT(*) AS locality_count FROM public.adrlocality;
SELECT COUNT(*) AS with_siruta FROM public.adrlocality WHERE siruta_code IS NOT NULL;
SELECT COUNT(*) AS with_hu FROM public.adrlocality WHERE name_hu IS NOT NULL;
-- Megyénkénti megoszlás
SELECT c.name_ro AS megye, COUNT(l.id) AS helyseg_count
FROM public.adrcounty c LEFT JOIN public.adrlocality l ON l.countyid = c.id
GROUP BY c.name_ro, c.auto_code ORDER BY c.auto_code;